template<int V, int NA>
__device__ __forceinline__ void bodyh(const float* __restrict__ go, const float* __restrict__ x, const float* __restrict__ s, float* __restrict__ y, long long n) {
    long long blk = (long long)blockIdx.x * (blockDim.x * 8 * V);
