                 : "memory")

__device__ __forceinline__ float silu_bwd(float g, float a, float b) {
    float one_minus = __fsub_rn(1.0f, b);
    float t = __fmul_rn(a, one_minus);
    float bracket = __fadd_rn(1.0f, t);
    float local = __fmul_rn(b, bracket);
    return __fmul_rn(g, local);
}

