template<int VEC, int UNR>
__device__ __forceinline__ void body(const float* __restrict__ g, const float* __restrict__ x, const float* __restrict__ s, float* __restrict__ o, long long n, long long base, int nthreads){
  // each thread handles UNR vectors of VEC floats, strided by nthreads
  long long nvec = n / VEC;
  float G[UNR][VEC], X[UNR][VEC], S[UNR][VEC];
  bool ok[UNR];
  #pragma unroll
  for(int u=0;u<UNR;u++){
    long long i = base + (long long)u*nthreads;
    ok[u] = i < nvec;
    if(ok[u]){
      if(VEC==8){ ld8(g+i*8,G[u]); ld8(x+i*8,X[u]); ld8(s+i*8,S[u]); }
      else { float4 a=*(const float4*)(g+i*4), b=*(const float4*)(x+i*4), c=*(const float4*)(s+i*4);
