  #pragma unroll
  for(int u=0;u<UNR;u++){
    long long i = base + (long long)u*nthreads;
    if(ok[u]){
      float O[VEC];
      #pragma unroll
      for(int k=0;k<VEC;k++) O[k]=silu_bw(G[u][k],X[u][k],S[u][k]);
      if(VEC==8) st8(o+i*8,O);
      else *(float4*)(o+i*4) = make_float4(O[0],O[1],O[2],O[3]);
    }
  }
  // tail
  if(base == nvec){ for(long long e=nvec*VEC;e<n;e++) o[e]=silu_bw(g[e],x[e],s[e]); }
}

