__device__ __forceinline__ unsigned long long pol_el(){ unsigned long long p; asm volatile("createpolicy.fractional.L2::evict_last.b64 %0, 1.0;" : "=l"(p)); return p; }
__device__ __forceinline__ float4 ld4(const float* p, unsigned long long pol){ float4 v;
  asm volatile("ld.global.L2::cache_hint.v4.f32 {%0,%1,%2,%3}, [%4], %5;" : "=f"(v.x),"=f"(v.y),"=f"(v.z),"=f"(v.w) : "l"(p),"l"(pol)); return v; }
__device__ __forceinline__ void st4(float* p, float4 v, unsigned long long pol){
  asm volatile("st.global.L2::cache_hint.v4.f32 [%0], {%1,%2,%3,%4}, %5;" :: "l"(p),"f"(v.x),"f"(v.y),"f"(v.z),"f"(v.w),"l"(pol) : "memory"); }
template<int BS,int UNR>
__global__ void __launch_bounds__(BS) kern(const float* __restrict__ g,const float* __restrict__ x,const float* __restrict__ s,float* __restrict__ o,long long n){
  long long nvec=n/4; long long base=(long long)blockIdx.x*(BS*UNR)+threadIdx.x;
  unsigned long long pe=pol_ef(), pl=pol_el();
  float4 A[UNR],B[UNR],C[UNR]; bool ok[UNR];
  #pragma unroll
  for(int u=0;u<UNR;u++){ long long i=base+u*BS; ok[u]=i<nvec; if(ok[u]){ A[u]=ld4(g+i*4,pe); B[u]=ld4(x+i*4,pe); C[u]=ld4(s+i*4,pe);} }
  #pragma unroll
  for(int u=0;u<UNR;u++){ long long i=base+u*BS; if(ok[u]){ float4 a=A[u],b=B[u],c=C[u];
    st4(o+i*4,make_float4(silu_bw(a.x,b.x,c.x),silu_bw(a.y,b.y,c.y),silu_bw(a.z,b.z,c.z),silu_bw(a.w,b.w,c.w)),pl);} }
  if(base==nvec){ for(long long e=nvec*4;e<n;e++) o[e]=silu_bw(g[e],x[e],s[e]); }
}
#define K(nm,B,U) extern "C" __global__ void nm(const float* g,const float* x,const float* s,float* o,long long n){ kern<B,U>(g,x,s,o,n); }
K(b256u1,256,1) K(b256u2,256,2) K(b256u4,256,4) K(b128u1,128,1) K(b128u2,128,2) K(b512u1,512,1) K(b512u2,512,2) K(b64u4,64,4)
'''
cfg={'b256u1':(256,1),'b256u2':(256,2),'b256u4':(256,4),'b128u1':(128,1),'b128u2':(128,2),'b512u1':(512,1),'b512u2':(512,2),'b64u4':(64,4)}
ks={nm:P.cuda_kernel(src,nm) for nm in cfg}
def ref(g,x,s): return g*(s*(1.0+x*(1.0-s)))
for n in [131,16384,262144,786432,2097152,8388608,16777216]:
    g,x,s=(torch.randn(n,device='cuda') for _ in range(3)); o=torch.empty(n,device='cuda'); r=ref(g,x,s)
    row=[]
    for nm,(bs,u) in cfg.items():
        grid=max(1,(n//4+1+bs*u-1)//(bs*u)); k=ks[nm]
        def fn(g,x,s,o,k=k,grid=grid,bs=bs): k((grid,1,1),(bs,1,1),g,x,s,o,n)
        o.zero_(); fn(g,x,s,o); torch.cuda.synchronize()
        bad=((o-r).abs()>1e-5+1e-5*r.abs()).sum().item(); assert bad==0,(nm,n,bad)
        row.append(f"{nm}:{P.harness_time(fn,(g,x,s),(o,)):.2f}")
    print(n, f"{n*16/1e6:.1f}MB", ' '.join(row))
# torch.compile estimate of a PyTorch-only baseline
def ref2(g,x,s): return g*(s*(1.0+x*(1.0-s)))
cref=torch.compile(ref2, dynamic=False)
print('--- torch.compile baseline estimate')
for n in [131,2053,16384,40960,163840,786432,2097152,8388608,16777216]:
    g,x,s=(torch.randn(n,device='cuda') for _ in range(3)); o=torch.empty(n,device='cuda')
    for _ in range(3): cref(g,x,s)
    torch.cuda.synchronize()
    def fn(g,x,s,o): o.copy_(cref(g,x,s))
    def fn2(g,x,s,o): torch.mul(g, s*(1.0+x*(1.0-s)), out=o)
    print(n, f"compile+copy:{P.harness_time(fn,(g,x,s),(o,)):.2f}", f"eager out=:{P.harness_time(fn2,(g,x,s),(o,)):.2f}")

